helpers = r'''
function applyOrderDecision(input: {
  current: OrderMemory;
  decision: FinalDecision;
  exactFacts: ProductFact[];
  exactReferences: ExactProductReference[];
  uploadedImageUrl?: string;
  signedInName?: string;
  signedInEmail?: string;
}) {
  const current = safeOrderMemory(input.current);
  const factsById = new Map(input.exactFacts.map((fact) => [fact.id, fact]));
  const refsById = new Map(input.exactReferences.filter((ref) => ref.id).map((ref) => [ref.id, ref]));
  const items = current.items.map((line) => ({ ...line, variant: line.variant ? { ...line.variant } : undefined }));
  let changed = false;
  for (const mutation of input.decision.orderMutations) {
    if (mutation.type === 'clear') { if (items.length) changed = true; items.splice(0, items.length); continue; }
    if (mutation.type === 'add') {
      const productId = cleanText(mutation.productId, 200);
      const fact = factsById.get(productId);
      if (!productId || !fact) continue;
      const quantity = Math.max(1, Math.min(50, Math.floor(mutation.quantity || 1)));
      const color = cleanText(mutation.color, 100);
      const size = cleanText(mutation.size, 100);
      const note = cleanText(mutation.note, 500);
      const selectedImage = safeHttpsUrl(refsById.get(productId)?.imageUrl);
      const uploadedImage = mutation.useUploadedImageAsReference ? safeHttpsUrl(input.uploadedImageUrl) : '';
      const imageUrl = uploadedImage || selectedImage || safeHttpsUrl(fact.imageUrl);
      const same = items.find((line) => line.productId === productId && normalizeSearchText(line.variant?.color || '') === normalizeSearchText(color) && normalizeSearchText(line.variant?.size || '') === normalizeSearchText(size) && (line.imageUrl || '') === imageUrl && normalizeSearchText(line.note || '') === normalizeSearchText(note));
      if (same) same.quantity = Math.min(50, same.quantity + quantity);
      else items.push({ lineId: `line_${crypto.randomUUID()}`, productId, quantity, ...(imageUrl ? { imageUrl } : {}), ...(color || size ? { variant: { ...(color ? { color } : {}), ...(size ? { size } : {}) } } : {}), ...(note ? { note } : {}) });
      changed = true;
      continue;
    }
    if (mutation.type === 'remove') {
      const lineId = cleanText(mutation.lineId, 120);
      const productId = cleanText(mutation.productId, 200);
      let index = lineId ? items.findIndex((line) => line.lineId === lineId) : -1;
      if (index < 0 && productId) for (let cursor = items.length - 1; cursor >= 0; cursor -= 1) { if (items[cursor].productId === productId) { index = cursor; break; } }
      if (index >= 0) { items.splice(index, 1); changed = true; }
      continue;
    }
    if (mutation.type === 'set_quantity') {
      const lineId = cleanText(mutation.lineId, 120);
      const productId = cleanText(mutation.productId, 200);
      const line = lineId ? items.find((item) => item.lineId === lineId) : items.find((item) => item.productId === productId);
      if (!line || mutation.quantity == null) continue;
      if (mutation.quantity <= 0) { const index = items.findIndex((item) => item.lineId === line.lineId); if (index >= 0) items.splice(index, 1); }
      else line.quantity = Math.max(1, Math.min(50, Math.floor(mutation.quantity)));
      changed = true;
    }
  }
  const customer = { ...(current.customer || {}) };
  if (input.signedInName && !customer.name) customer.name = cleanText(input.signedInName, 120);
  if (input.signedInEmail && !customer.email) customer.email = cleanText(input.signedInEmail, 240);
  for (const [key, raw] of Object.entries(input.decision.customerDetails)) { const value = cleanText(raw, key === 'address' ? 500 : key === 'email' ? 240 : 120); if (value) (customer as Record<string, string>)[key] = value; }
  const payment = { ...(current.payment || {}) };
  if (input.decision.paymentProofAccepted) { payment.proofSeen = true; if (input.decision.paymentAmount != null) payment.amount = input.decision.paymentAmount; const uploaded = safeHttpsUrl(input.uploadedImageUrl); if (uploaded) payment.imageUrl = uploaded; }
  let stage = current.stage;
  if (!items.length) stage = 'collecting';
  else if (input.decision.orderAction === 'draft') stage = 'draft';
  else if (input.decision.orderAction === 'finalize' || input.decision.orderAction === 'place') stage = 'final';
  else if (changed && stage === 'final') stage = 'draft';
  return { items: items.slice(0, 30), stage, ...(Object.keys(customer).length ? { customer } : {}), ...(Object.keys(payment).length ? { payment } : {}) } satisfies OrderMemory;
}

function orderCards(order: OrderMemory, facts: ProductFact[]) {
  const byId = new Map(facts.map((fact) => [fact.id, fact]));
  return order.items.map((line) => {
    const fact = byId.get(line.productId); if (!fact) return null;
    const card = productCard(fact);
    const referenceImageUrl = safeHttpsUrl(line.imageUrl);
    return { ...card, imageUrl: referenceImageUrl || card.imageUrl, orderLineId: line.lineId, quantity: line.quantity, ...(line.variant ? { variant: line.variant } : {}), ...(line.note ? { selectionNote: line.note } : {}), ...(referenceImageUrl ? { referenceImageUrl } : {}) } satisfies ProductCard;
  }).filter(Boolean) as ProductCard[];
}

function orderCustomerComplete(customer?: OrderCustomer) { return Boolean(customer?.name && customer?.phone && customer?.city && customer?.address); }

'''
