s = regex_once(s, r"  const exactCards = candidates\.exactProductFacts\.map\(productCard\);\n  const orderProducts = decision\.orderAction === 'draft'.*?  const nextContext: ChatContext = \{\n    lastProductQuery: interpretation\.catalogueMode === 'products' && interpretation\.searchText \? interpretation\.searchText : context\.lastProductQuery,\n    shownProductIds: \[\.\.\.new Set\(nextShown\)\],\n  \};", """  const appliedOrder = applyOrderDecision({\n    current: safeOrderMemory(context.order),\n    decision,\n    exactFacts: candidates.exactProductFacts,\n    exactReferences: exactProductReferences,\n    uploadedImageUrl: customerImageUrl,\n    signedInName: customerName,\n    signedInEmail: customerEmail,\n  });\n  const orderProducts = orderCards(appliedOrder, candidates.exactProductFacts);\n  let orderAction: OrderAction = decision.orderAction;\n  if (orderAction === 'place' && (!orderProducts.length || appliedOrder.stage !== 'final' || !orderCustomerComplete(appliedOrder.customer))) orderAction = 'finalize';\n\n  const nextShown = [...(context.shownProductIds || []), ...products.map((product) => product.id)].filter(Boolean).slice(-MAX_SHOWN_IDS);\n  const nextContext: ChatContext = {\n    lastProductQuery: interpretation.catalogueMode === 'products' && interpretation.searchText ? interpretation.searchText : context.lastProductQuery,\n    shownProductIds: [...new Set(nextShown)],\n    order: appliedOrder,\n  };""", 'engine apply order state')
