p = 'components/salar/SalarWidget.tsx'
s = read(p)
s = replace_once(s, """  stock?: number;\n  category?: string;\n};""", """  stock?: number;\n  category?: string;\n  orderLineId?: string;\n  quantity?: number;\n  variant?: { color?: string; size?: string };\n  selectionNote?: string;\n  referenceImageUrl?: string;\n};""", 'widget ProductCard fields')
s = replace_once(s, """type ChatContext = {\n  lastProductQuery?: string;\n  shownProductIds?: string[];\n};""", """type ChatContext = {\n  lastProductQuery?: string;\n  shownProductIds?: string[];\n  order?: {\n    items?: Array<{ lineId: string; productId: string; quantity: number; imageUrl?: string; variant?: { color?: string; size?: string }; note?: string }>;\n    stage?: 'collecting' | 'draft' | 'final';\n    customer?: Partial<OrderCustomer>;\n    payment?: { proofSeen?: boolean; amount?: number; imageUrl?: string };\n  };\n};""", 'widget ChatContext')
s = regex_once(s, r"function detailsFromMessage\(message: string\) \{.*?\n\}\n\nfunction customerComplete", """function customerComplete""", 'widget remove regex detail parser')
s = replace_once(s, """        body: JSON.stringify({ mode: 'quote', items: items.map((item) => ({ productId: item.id, quantity: item.quantity })) }),""", """        body: JSON.stringify({ mode: 'quote', items: items.map((item) => ({\n          productId: item.id,\n          quantity: item.quantity,\n          ...(item.variant ? { variant: item.variant } : {}),\n          customerReferenceImage: item.referenceImageUrl || item.imageUrl || '',\n          selectionNote: item.selectionNote || '',\n        })) }),""", 'widget quote payload')
s = regex_once(s, r"  async function startOrderDraft\(products: ProductCard\[\]\) \{.*?\n  \}\n\n  function changeQuantity\(id: string, delta: number\) \{.*?\n  \}", """  async function startOrderDraft(products: ProductCard[]) {\n    const unique = [...new Map(products.map((product) => [product.orderLineId || `${product.id}:${product.variant?.color || ''}:${product.variant?.size || ''}:${product.referenceImageUrl || ''}`, product])).values()].slice(0, 30);\n    if (!unique.length) return [] as OrderItem[];\n    const items = unique.map((product) => ({ ...product, imageUrl: product.referenceImageUrl || product.imageUrl, quantity: Math.max(1, Math.min(50, Math.floor(Number(product.quantity) || 1))) }));\n    setOrderItems(items);\n    setOrderId('');\n    setOrderQuote(null);\n    setOrderError('');\n    await quoteOrder(items);\n    return items;\n  }\n\n  function changeQuantity(key: string, delta: number) {\n    const next = orderItems.map((item) => (item.orderLineId || item.id) === key ? { ...item, quantity: Math.max(1, Math.min(50, item.quantity + delta)) } : item);\n    setOrderItems(next);\n    void quoteOrder(next);\n  }""", 'widget order draft helpers')
s = replace_once(s, """          customer: { ...customer, notes: 'Order prepared through Salar chat.' },\n          items: items.map((item) => ({ productId: item.id, quantity: item.quantity })),""", """          customer: {\n            ...customer,\n            notes: [\n              'Order prepared through AI sales chat.',\n              ...items.map((item, index) => {\n                const details = [item.variant?.color ? `colour=${item.variant.color}` : '', item.variant?.size ? `size=${item.variant.size}` : '', item.selectionNote || '', item.referenceImageUrl ? `reference=${item.referenceImageUrl}` : ''].filter(Boolean).join(', ');\n                return details ? `${index + 1}. ${item.title}: ${details}` : '';\n              }).filter(Boolean),\n            ].join('\\n'),\n          },\n          items: items.map((item) => ({\n            productId: item.id,\n            quantity: item.quantity,\n            ...(item.variant ? { variant: item.variant } : {}),\n            customerReferenceImage: item.referenceImageUrl || item.imageUrl || '',\n            selectionNote: item.selectionNote || '',\n          })),""", 'widget place order payload')
s = replace_once(s, """    const parsedDetails = detailsFromMessage(message);\n    const mergedCustomer = { ...orderCustomer, ...parsedDetails };\n    if (Object.keys(parsedDetails).length) setOrderCustomer(mergedCustomer);\n\n""", "", 'widget remove detail heuristics')
s = replace_once(s, """      const modelOrderProducts: ProductCard[] = Array.isArray(result?.orderProducts)\n        ? result.orderProducts.filter((product: any) => product?.id && product?.title).slice(0, 30)\n        : [];\n      if (result?.orderAction === 'draft' && modelOrderProducts.length) {\n        await startOrderDraft(modelOrderProducts);\n      }""", """      const modelCustomer = result?.orderCustomer && typeof result.orderCustomer === 'object' ? result.orderCustomer as Partial<OrderCustomer> : {};\n      const nextCustomer: OrderCustomer = {\n        ...orderCustomer,\n        ...modelCustomer,\n        name: String(modelCustomer.name || orderCustomer.name || customerName || '').trim(),\n        email: String(modelCustomer.email || orderCustomer.email || customerEmail || '').trim(),\n        phone: String(modelCustomer.phone || orderCustomer.phone || '').trim(),\n        city: String(modelCustomer.city || orderCustomer.city || '').trim(),\n        address: String(modelCustomer.address || orderCustomer.address || '').trim(),\n      };\n      if (Object.values(modelCustomer).some((value) => String(value || '').trim()) || customerName || customerEmail) setOrderCustomer(nextCustomer);\n      const modelOrderProducts: ProductCard[] = Array.isArray(result?.orderProducts)\n        ? result.orderProducts.filter((product: any) => product?.id && product?.title).slice(0, 30)\n        : [];\n      let nextItems: OrderItem[] = [];\n      if ((result?.orderAction === 'draft' || result?.orderAction === 'finalize' || result?.orderAction === 'place') && modelOrderProducts.length) nextItems = await startOrderDraft(modelOrderProducts);\n      if (result?.orderAction === 'place' && nextItems.length && customerComplete(nextCustomer)) await placeChatOrder(false, nextItems, nextCustomer);""", 'widget model-driven order response')
s = replace_once(s, """    const products = [...selectedProducts];\n    await startOrderDraft(products);\n    setText('');\n    await sendMessage('Ye selected products mera order draft bana dein.', null, '', products);""", """    const products = [...selectedProducts];\n    setText('');\n    await sendMessage('Ye selected products mera order draft bana dein.', null, '', products);""", 'widget make order brain first')
s = replace_once(s, """{orderItems.map((item) => <div key={item.id} className=\"flex items-center gap-2 rounded-xl bg-[#F6F6F2] p-2\">{item.imageUrl ? <img src={item.imageUrl} alt=\"\" className=\"h-10 w-10 rounded-lg object-cover\"/> : null}<p className=\"min-w-0 flex-1 line-clamp-2 text-[9px] font-bold\">{item.title}</p><div className=\"flex items-center gap-1\"><button type=\"button\" onClick={() => changeQuantity(item.id, -1)}""", """{orderItems.map((item) => <div key={item.orderLineId || item.id} className=\"flex items-center gap-2 rounded-xl bg-[#F6F6F2] p-2\">{item.imageUrl ? <img src={item.imageUrl} alt=\"\" className=\"h-10 w-10 rounded-lg object-cover\"/> : null}<div className=\"min-w-0 flex-1\"><p className=\"line-clamp-2 text-[9px] font-bold\">{item.title}</p>{item.variant?.color || item.variant?.size || item.selectionNote ? <p className=\"mt-0.5 line-clamp-2 text-[8px] text-black/45\">{[item.variant?.color, item.variant?.size, item.selectionNote].filter(Boolean).join(' • ')}</p> : null}</div><div className=\"flex items-center gap-1\"><button type=\"button\" onClick={() => changeQuantity(item.orderLineId || item.id, -1)}""", 'widget order card line start')
s = replace_once(s, """onClick={() => changeQuantity(item.id, 1)}""", """onClick={() => changeQuantity(item.orderLineId || item.id, 1)}""", 'widget order card plus')
